    cy.get('[data-testid="card-expiry-input"]').type(cardExpiry);
    cy.get('[data-testid="card-cvc-input"]').type(cardCVC);
    cy.get('[data-testid="cardholder-name-input"]').type('John Doe');

    // Submit payment
    cy.get('[data-testid="pay-button"]').click();

    // Verify order confirmation page
    cy.get('[data-testid="confirmation-page"]').should('be.visible');
    cy.get('[data-testid="order-success-message"]').should('contain', 'Order Confirmed');
    cy.get('[data-testid="order-number"]').should('be.visible').and('not.be.empty');
    cy.get('[data-testid="confirmation-email"]').should('contain', testEmail);
    cy.get('[data-testid="order-total"]').should('contain', productPrice);

    // Verify confirmation email was sent
    cy.get('[data-testid="email-confirmation-notice"]').should('contain', 'confirmation email has been sent');
  });

